import * as db from './storage.mjs';
import {createPerson,createMeeting,createInterview,writeAnswer,updateInterview,addInterviewNote,appliesToPermit} from './interviews.mjs';
import {QUESTIONS,THEMES,ROLES,getQuestions,isQuestionVisible} from './interview-library.mjs';
import {buildInterviewReport,interviewCSV,interviewHTML,createInterviewWordReport} from './interview-export.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const timestamp=()=>new Date().toISOString();
const input=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const opt=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
const select=(name,label,options,value='')=>`<label class="field"><span>${esc(label)}</span><select name="${name}">${options.map(o=>opt(Array.isArray(o)?o[0]:o,Array.isArray(o)?o[1]:o,value)).join('')}</select></label>`;
const area=(name,label,value='',extra='')=>`<label class="field"><span>${esc(label)}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const when=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleString('fr-FR',{dateStyle:'medium',...(v.length===10?{}:{timeStyle:'short'})}):'Date non renseignée';
const act=(action,label,extra='',cls='')=>`<button type="button" data-iv-action="${action}" ${extra} class="${cls}">${label}</button>`;
const provenance=[['declaration','Déclaration directe'],['observed','Fait personnellement observé'],['third-party','Information rapportée par un tiers'],['document','Document présenté'],['verified','Vérification ultérieure']];
const quality=[['to-confirm','À confirmer'],['confirmed','Confirmé'],['contradictory','Contradictoire'],['outdated','À actualiser']];
const specials=[['unknown','Ne sait pas'],['not-applicable','Non applicable'],['refused','Refuse de répondre'],['verify','À vérifier'],['skipped','Passer']];
const readable=v=>Array.isArray(v)?v.join(', '):v&&typeof v==='object'?Object.entries(v).map(([k,x])=>`${k} : ${x}`).join(' · '):String(v??'');

/** Additive metadata only: absent geometry is never fabricated. */
export function seedInterviewPermits(permits){
 const additions=[['39985',64,'Volomborona','Tsiatosika','Mananjary'],['40378',145,'Ambalafary','Marosangy','Mananjary'],['40466',73,'Ambohimandroso','Ampasimanjeva','Manakara Atsimo']];
 return [...permits,...additions.filter(([id])=>!permits.some(p=>p.id===id)).map(([id,declaredCount,fokontany,commune,district])=>({id,count:0,declaredCount,cells:[],contours:[],district,communes:[{name:commune,count:declaredCount}],fokontany,status:null,adminVerificationRequired:true,metadataSource:'Informations du projet Entretiens ; statut et géométrie à vérifier.'}))];
}

export async function mountInterviews(root,{permits,observations,notify,deliver,onPermitsChanged,isCurrent=()=>true}={}){
 let destroyed=false,iv=null,people=[],meetings=[],interviews=[],settings=[],assets=[],queue=Promise.resolve(),all=false,index=0,theme='',search='',panel='',pendingQuestion=null;
 const urls=new Map(),params=new URLSearchParams(location.hash.split('?')[1]||''),filters={permit:params.get('permit')||'',district:'',commune:'',person:'',role:'',from:'',to:'',theme:'',verify:false};
 let view=params.get('view')||'list',reportKind='comparison',editingQuestionId=null;
 const currentPerson=()=>iv?.personSnapshot||people.find(p=>p.id===iv?.personId)||{};
 const qlist=()=>{const overrides=settings.find(s=>s.id==='interview-question-overrides')?.value||{},catalog=new Map();for(const q of [...QUESTIONS,...settings.filter(s=>s.id==='interview-questions'||s.id.startsWith('interview-questions~')).flatMap(s=>Array.isArray(s.value)?s.value:[]),...(iv?.customQuestions||[]),...Object.values(iv?.answers||{}).map(a=>a.questionSnapshot)])if(q&&!catalog.has(q.id))catalog.set(q.id,iv?.answers[q.id]?.questionSnapshot||({...q,...overrides[q.id]}));return [...catalog.values()];};
 const suggestionsFor=q=>[...new Set([...(q.options||[]),...(q.suggestions||[]),...(settings.find(s=>s.id==='interview-suggestions')?.value?.[q.id]||[])])];
 const query=sel=>root.querySelector(sel);
 async function reload(){[people,meetings,interviews,settings,assets]=await Promise.all([db.readAll('interviewPeople'),db.readAll('interviewMeetings'),db.readInterviews(),db.readAll('settings'),db.readAll('assets')]);}
 const roleList=()=>[...new Set([...ROLES,...people.map(p=>p.role).filter(Boolean)])];
 function saveStatus(label,error=false){const el=query('#iv-save-status');if(el){el.textContent=label;el.classList.toggle('iv-error',error);}}
 function persist(){const snapshot=structuredClone(iv);saveStatus('Enregistrement…');const saving=db.saveInterviewDraft(snapshot);queue=queue.catch(()=>{}).then(()=>saving).then(()=>saveStatus('Conservé sur cet appareil')).catch(e=>{saveStatus('Échec de sauvegarde · réessayez et exportez',true);notify(e.message);throw e;});return queue;}
 function patch(p){iv=updateInterview(iv,p);return persist();}
 function answer(q,p){iv=writeAnswer(iv,q,p);return persist();}
 async function setting(id,value){const rec={id,value,updatedAt:timestamp()};await db.put('settings',rec);settings=settings.filter(s=>s.id!==id).concat(rec);}
 function permitsMarkup(selected=[],name='permitIds'){return `<div class="iv-permits">${permits.map(p=>`<label><input type="checkbox" name="${name}" value="${esc(p.id)}" ${selected.includes(p.id)?'checked':''}> <strong>${esc(p.id)}</strong> <small>${esc(p.district||'Localisation à préciser')}</small></label>`).join('')}</div>`;}
 function personFields(p={}){return `${input('name','Nom et prénom',p.name,'text','required maxlength="240"')}${input('role','Fonction ou qualité',p.role||'Maire','text','list="iv-roles" required maxlength="240"')}<datalist id="iv-roles">${roleList().map(r=>`<option value="${esc(r)}">`).join('')}</datalist>${input('institution','Institution ou organisme',p.institution)}<div class="two">${input('district','District',p.district)}${input('commune','Commune',p.commune)}</div>${input('fokontany','Fokontany',p.fokontany)}${input('contact','Contact facultatif',p.contact,'tel')}${area('notes','Notes de la fiche',p.notes)}`;}
 function exportsMarkup(kind){return `<details class="iv-exports"><summary>Exporter · ${esc(kind)}</summary><div class="quick-actions">${act('export-csv','Tableau CSV')}${act('export-word','Document Word')}${act('export-print','Imprimer / PDF')}${act('export-html','Rapport HTML')}${act('backup','Sauvegarde JSON complète')}</div><p class="muted">Les rapports nomment les sources et les pièces. La sauvegarde complète conserve les fichiers et l’historique. Les exports contiennent des données personnelles.</p></details>`;}
 function card(item){const p=item.personSnapshot||people.find(x=>x.id===item.personId)||{},m=meetings.find(x=>x.id===item.meetingId);return `<article class="card"><div class="section-head iv-section"><h2>${esc(p.name||'Interlocuteur à compléter')}</h2><span class="tag">${item.status==='complete'?'Terminé':'À poursuivre'}</span></div><p>${esc(p.role)} · ${when(item.date)}<br><span class="muted">${esc(item.permitIds.join(', ')||'Entretien général')} · ${esc(item.location||p.commune||'Lieu à préciser')}${m?' · '+esc(m.title):''}</span></p><p class="muted">${Object.values(item.answers).filter(a=>a.status!=='skipped').length} réponses · ${esc(item.mode==='quick'?'Rapide':'Complet')}</p><a class="iv-button" href="#interviews?id=${encodeURIComponent(item.id)}">Ouvrir l’entretien →</a></article>`;}
 function list(){const items=interviews.filter(x=>!filters.permit||x.permitIds.includes(filters.permit)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return `<div class="page-head"><div><p class="eyebrow">Consultations de terrain</p><h1>Entretiens</h1><p>Une personne, un entretien. Réponses et pièces conservées hors ligne.</p></div>${act('new','+ Nouvel entretien','','primary')}</div><div class="quick-actions">${act('meeting','Nouvelle réunion')}${act('people','Interlocuteurs')}${act('compare','Synthèse et comparaison')}${act('library','Personnaliser les questions')}</div><div class="filters iv-top">${select('iv-filter-permit','Permis',[['','Tous les permis'],...permits.map(p=>[p.id,p.id])],filters.permit)}</div>${items.length?items.map(card).join(''):'<div class="card empty"><h2>Prêt pour la prochaine rencontre</h2><p>Commencez par la personne et les permis concernés.</p></div>'}<details><summary>Réunions · ${meetings.length}</summary>${meetings.map(m=>`<article class="card"><h3>${esc(m.title)}</h3><p>${when(m.date)} · ${esc(m.location)} · ${interviews.filter(i=>i.meetingId===m.id).length} entretiens</p><div class="quick-actions">${act('new-in-meeting','Ajouter un interlocuteur',`data-id="${esc(m.id)}"`)}${act('meeting-report','Compte rendu',`data-id="${esc(m.id)}"`)}${act('edit-meeting','Modifier',`data-id="${esc(m.id)}"`)}</div></article>`).join('')}</details>${exportsMarkup('tous les entretiens')}`;}
 function setup(meetingId=''){return `<h1>Nouvel entretien</h1><form id="iv-create" data-meeting="${esc(meetingId)}"><div class="form-grid"><section class="card"><h2>Interlocuteur</h2>${select('personId','Personne enregistrée',[['','Créer une nouvelle personne'],...people.map(p=>[p.id,`${p.name} · ${p.role}`])])}<div id="iv-new-person">${personFields()}</div></section><section class="card"><h2>Contexte de la rencontre</h2>${select('meetingId','Réunion',[['','Entretien indépendant'],...meetings.map(m=>[m.id,`${m.title} · ${m.date}`])],meetingId)}${input('date','Date de l’entretien',today(),'date','required')}${input('location','Lieu de l’entretien')}${select('mode','Mode de collecte',[['quick','Rapide · questions essentielles'],['complete','Complet · tous les thèmes']],'quick')}<h3>Permis concernés</h3><p class="muted">Aucun permis coché : entretien général.</p>${permitsMarkup()}<details><summary>Ajouter un numéro de permis</summary>${input('manualPermit','Nouveau numéro de permis','','text','inputmode="numeric" pattern="[0-9]{1,12}" maxlength="12"')}<p class="muted">Son statut restera à vérifier.</p></details><button type="submit" class="primary">Démarrer l’entretien</button></section></div></form>${act('list','Retour aux entretiens')}`;}
 function meetingForm(id=''){const m=meetings.find(m=>m.id===id)||{};return `<h1>${id?'Modifier la réunion':'Nouvelle réunion'}</h1><form id="iv-meeting" data-id="${esc(id)}" class="card">${input('title','Titre de la réunion',m.title,'text','required maxlength="240"')}${input('date','Date',m.date||today(),'date','required')}${input('location','Lieu',m.location)}${permitsMarkup(m.permitIds||[])}${area('notes','Notes de réunion',m.notes)}<button class="primary" type="submit">Enregistrer la réunion</button></form>${act('list','Retour')}`;}
 function peoplePage(){return `<h1>Interlocuteurs</h1><p>Chaque rencontre garde sa propre fiche source et ses réponses. Modifier la fiche prépare les rencontres suivantes.</p>${people.map(p=>`<article class="card"><h2>${esc(p.name)}</h2><p>${esc(p.role)} · ${esc(p.commune)} · ${interviews.filter(i=>i.personId===p.id).length} entretiens</p>${act('edit-person','Modifier la fiche',`data-id="${esc(p.id)}"`)}</article>`).join('')}${act('list','Retour aux entretiens')}`;}
 function personForm(id){const p=people.find(p=>p.id===id);return `<h1>Fiche interlocuteur</h1><form id="iv-person" data-id="${esc(id)}" class="card">${personFields(p)}<button type="submit" class="primary">Enregistrer la fiche</button></form>${act('people','Retour')}`;}
 function fileMarkup(ids=[],captions={}){return ids.map(id=>{const a=assets.find(x=>x.id===id);if(!a)return '';if(!urls.has(id))urls.set(id,URL.createObjectURL(a.blob));return `<div class="attachment">${a.type?.startsWith('image/')?`<img src="${urls.get(id)}" alt="${esc(captions[id]||a.name)}">`:''}<a href="${urls.get(id)}" download="${esc(a.name)}">${esc(a.name)}</a><label class="field"><span>Légende ${esc(a.name)}</span><input data-iv-caption="${esc(id)}" value="${esc(captions[id]||'')}"></label></div>`;}).join('');}
 function valueInput(q,a){const choices=suggestionsFor(q),value=a.value;
  if(['boolean','select','multi'].includes(q.type))return `<div class="chips iv-choices">${choices.map(v=>act('choice',esc(v),`data-value="${esc(v)}" aria-pressed="${Array.isArray(value)?value.includes(v):value===v}"`,(Array.isArray(value)?value.includes(v):value===v)?'selected':'')).join('')}</div>${input('iv-other','Autre / réponse libre',Array.isArray(value)?value.filter(v=>!choices.includes(v)).join('; '):typeof value==='string'&&!choices.includes(value)?value:'')}`;
  if(q.type==='number')return input('iv-value',`Valeur${q.unit?' ('+q.unit+')':''}`,value??'','number','step="any" inputmode="decimal"');
  if(q.type==='date')return `${input('iv-value','Date connue',value??'','date')}${input('iv-period','Ou période déclarée',a.period||'')}`;
  if(q.type==='location')return `${act('gps','Relever le GPS')}<div class="two">${input('iv-lat','Latitude',value?.lat??'','number','step="any" min="-90" max="90" inputmode="decimal"')}${input('iv-lng','Longitude',value?.lng??'','number','step="any" min="-180" max="180" inputmode="decimal"')}</div><p class="muted">${value?.accuracy!=null?'Précision ± '+esc(value.accuracy)+' m':'Saisie manuelle possible'}</p>`;
  return `${choices.length?`<div class="chips">${choices.map(v=>act('suggestion',esc(v),`data-value="${esc(v)}"`)).join('')}</div>`:''}${area('iv-value',q.type==='observation'?'Observation / document présenté':'Réponse',value??'')}`;
 }
 function questionCard(q){const a=iv.answers[q.id]||{},scope=a.scope||{type:'all',permitIds:[]};return `<section class="card iv-question" data-question="${esc(q.id)}"><p class="eyebrow">${esc(THEMES.find(t=>t.id===q.theme)?.label||'Questions libres')} · ${esc(({high:'priorité haute',normal:'priorité normale',low:'priorité basse'})[q.priority]||q.priority||'priorité normale')}</p><h2>${esc(q.label)}</h2>${!isQuestionVisible(q,iv.answers)?'<p class="notice">Question conditionnelle affichée pour consultation. Sa condition actuelle n’est pas remplie ; les réponses déjà saisies sont conservées.</p>':''}${valueInput(q,a)}<div class="chips iv-top">${specials.map(([key,label])=>act('special',label,`data-value="${key}" aria-pressed="${a.status===key}"`,a.status===key?'selected':'quiet')).join('')}</div>${area('iv-complement','Complément / notes de cette réponse',a.complement||'')}<div class="quick-actions">${act('revisit',a.revisit?'✓ À reprendre':'Marquer à reprendre',`aria-pressed="${!!a.revisit}"`)}${act('camera-question','Prendre une photo')}${act('attach-question','Photo / document')}${act('learn','Mémoriser une suggestion')}</div><details ${iv.mode==='complete'||panel==='reliability'?'open':''}><summary>Portée, source et fiabilité</summary>${select('iv-scope','Cette réponse concerne',[['all','Tous les permis de cet entretien'],['permits','Un ou plusieurs permis précis'],['commune','La commune en général'],['district','Le district en général'],['general','Information générale']],scope.type)}${scope.type==='permits'?permitsMarkup(scope.permitIds,'answerPermits'):''}${select('iv-provenance','Provenance',provenance,a.provenance||'declaration')}${select('iv-quality','Fiabilité',quality,a.quality||'to-confirm')}${input('iv-source','Personne / référence source',a.source||currentPerson().name||'')}${input('iv-answer-date','Date de l’information',a.date?.slice(0,10)||iv.date,'date')}<p class="muted">Le statut « Confirmé » reste une appréciation explicite de l’enquêteur. Une déclaration reste identifiée comme telle.</p>${select('iv-observation','Lier une observation de terrain',[['','Aucune'],...observations.map(o=>[o.id,o.title||o.id])],a.observationIds?.[0]||'')}</details><div class="attachments">${fileMarkup(a.assetIds,a.captions)}</div>${a.updatedAt?`<small class="muted">Dernière modification : ${when(a.updatedAt)}</small>`:''}</section>`;}
 function editor(){const p=currentPerson(),qs=getQuestions({role:p.role,mode:iv.mode,answers:iv.answers,questions:qlist(),theme,search,includeAll:all,includeHidden:all});index=Math.max(0,Math.min(index,qs.length-1));const q=qs[index],answered=qs.filter(q=>iv.answers[q.id]&&iv.answers[q.id].status!=='skipped').length;return `<div class="page-head"><div><p class="eyebrow">${esc(p.role)} · ${esc(iv.permitIds.join(', ')||'Entretien général')}</p><h1>${esc(p.name)}</h1><p>${when(iv.date)} · ${esc(iv.location||p.commune)}${iv.status==='complete'?' · Terminé':''}</p></div>${act('list','Fermer')}</div><details><summary>Contexte de l’entretien</summary><div class="card">${input('iv-date','Date de l’entretien',iv.date,'date')}${input('iv-location','Lieu de l’entretien',iv.location)}${select('iv-meeting','Réunion',[['','Indépendant'],...meetings.map(m=>[m.id,m.title])],iv.meetingId||'')}<h3>Permis associés</h3>${permitsMarkup(iv.permitIds,'iv-permits')}<p class="muted">${esc(p.institution)} · ${esc(p.district)} · ${esc(p.commune)} · ${esc(p.fokontany)}</p></div></details><div class="iv-layout"><aside><div class="card"><div class="quick-actions iv-mode-controls">${act('mode',iv.mode==='quick'?'Mode Complet':'Mode Rapide')}${act('all',all?'Questions du profil':'Tout afficher',`aria-pressed="${all}"`)}</div><details ${iv.mode==='complete'?'open':''}><summary>Thèmes, recherche et navigation</summary>${select('iv-theme','Thème',[['','Tous les thèmes'],...THEMES.map(t=>[t.id,t.label])],theme)}${input('iv-search','Rechercher une question',search,'search')}<p class="muted iv-progress-label">${answered} / ${qs.length} questions renseignées</p><progress max="${qs.length||1}" value="${answered}" aria-label="Avancement"></progress>${select('iv-jump','Aller à une question',qs.map((q,i)=>[String(i),`${iv.answers[q.id]?'✓ ':''}${q.label}`]),String(index))}${act('custom','+ Question libre')}</details><p class="muted iv-progress-label">${answered} / ${qs.length} questions renseignées</p></div></aside><div>${q?questionCard(q):'<div class="card"><h2>Aucune question dans ce filtre</h2><p>Changez de thème ou affichez toutes les questions.</p></div>'}<div class="iv-bottom"><div class="quick-actions">${act('previous','← Précédente',index===0?'disabled':'')}${act('next','Suivante →',index>=qs.length-1?'disabled':'','primary')}${act('note','+ Note')}</div><p id="iv-save-status" class="draft-status" role="status">Conservé sur cet appareil</p></div><details id="iv-notes" ${panel==='notes'?'open':''}><summary>Notes générales · ${iv.noteEntries?.length||0}</summary>${area('iv-notes','Bloc-notes indépendant',iv.notes||'')}<p class="muted">Le clavier du téléphone peut proposer la dictée vocale.</p><form id="iv-note">${area('note','Ajouter une note horodatée')}<button type="submit">Ajouter la note</button></form>${(iv.noteEntries||[]).map(n=>`<p><small>${when(n.createdAt||n.at||n.date)}</small><br>${esc(n.text||n.note)}</p>`).join('')}<div class="quick-actions">${act('attach-general','Joindre une pièce générale')}</div><div class="attachments">${fileMarkup(iv.assetIds,iv.captions)}</div></details><details><summary>Historique · ${iv.history.length} changements</summary>${iv.history.slice(-50).reverse().map(h=>`<p><small>${when(h.at||h.date||h.updatedAt)}</small> · ${esc(h.questionId||h.type||h.action||'Modification')}</p>`).join('')}</details>${act('finish',iv.status==='complete'?'Reprendre cet entretien':'Terminer l’entretien','','primary')}${exportsMarkup('fiche individuelle')}</div></div><input id="iv-files" type="file" accept="image/*,application/pdf,text/plain,audio/*" multiple hidden><input id="iv-camera" type="file" accept="image/*" capture="environment" hidden>`;}
 function filtered(){return interviews.filter(i=>{const p=i.personSnapshot||people.find(p=>p.id===i.personId)||{};return (!filters.permit||i.permitIds.includes(filters.permit))&&(!filters.district||p.district===filters.district)&&(!filters.commune||p.commune===filters.commune)&&(!filters.person||i.personId===filters.person)&&(!filters.role||p.role===filters.role)&&(!filters.from||i.date>=filters.from)&&(!filters.to||i.date<=filters.to);});}
 function reportOptions(kind=reportKind){return {kind,interviews:iv?[iv]:filtered(),people,meetings,assets,questions:qlist(),theme:iv?undefined:filters.theme||undefined,unconfirmedOnly:iv?false:filters.verify,permitId:iv?undefined:filters.permit||undefined,interviewId:iv?.id,meetingId:panel.startsWith('meeting:')?panel.slice(8):undefined,mappings:settings.find(s=>s.id==='interview-mappings')?.value||{}};}
 function reportMarkup(report){return `<article class="iv-report"><h2>${esc(report.title)}</h2>${report.sections.map(s=>`<section class="card"><h3>${esc(s.title)}</h3>${(s.paragraphs||[]).map(p=>`<p>${esc(p)}</p>`).join('')}${s.rows?.length?`<div class="table-scroll"><table><thead><tr>${(s.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.rows.map(row=>`<tr>${(Array.isArray(row)?row:Object.values(row)).map(v=>`<td>${esc(readable(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</section>`).join('')}</article>`;}
 function compare(){const unique=key=>[...new Set(people.map(p=>p[key]).filter(Boolean))];return `<h1>Synthèse et comparaison</h1><p>Les déclarations restent séparées. Les divergences signalent des vérifications à conduire.</p><div class="iv-filter-grid">${select('filter-permit','Permis',[['','Tous les permis'],...permits.map(p=>[p.id,p.id])],filters.permit)}${select('filter-district','District',[['','Tous'],...unique('district')],filters.district)}${select('filter-commune','Commune',[['','Toutes'],...unique('commune')],filters.commune)}${select('filter-person','Interlocuteur',[['','Tous'],...people.map(p=>[p.id,p.name])],filters.person)}${select('filter-role','Fonction',[['','Toutes'],...roleList()],filters.role)}${input('filter-from','À partir du',filters.from,'date')}${input('filter-to','Jusqu’au',filters.to,'date')}${select('filter-theme','Thème',[['','Tous'],...THEMES.map(t=>[t.id,t.label])],filters.theme)}</div><label class="review-check"><input type="checkbox" name="filter-verify" ${filters.verify?'checked':''}> Informations à confirmer ou à reprendre</label><div class="quick-actions">${act('comparison','Comparer les témoignages')}${act('summary','Synthèse par permis')}${act('missing','Informations à compléter')}${act('list','Retour')}</div>${reportKind==='permit'&&!filters.permit?'<p class="notice">Sélectionnez un permis pour préparer sa synthèse documentaire.</p>':reportMarkup(buildInterviewReport(reportOptions()))}${exportsMarkup(reportKind==='permit'?'synthèse par permis':reportKind==='missing'?'informations à compléter':'comparaison')}`;}
 function customForm(){if(editingQuestionId){const q=qlist().find(q=>q.id===editingQuestionId);return `<h1>Personnaliser une question</h1><form id="iv-question-edit" class="card">${input('label','Question',q.label,'text','required maxlength="1000"')}${select('theme','Thème',THEMES.map(t=>[t.id,t.label]),q.theme)}${select('type','Type',[['text','Texte libre'],['boolean','Oui / Non'],['select','Choix unique'],['multi','Choix multiples'],['number','Nombre avec unité'],['date','Date ou période'],['location','Localisation GPS'],['observation','Observation et pièce jointe']],q.type)}${input('options','Suggestions séparées par un point-virgule',suggestionsFor(q).join('; '))}${input('destination','Rubrique documentaire',q.destination)}${input('unit','Unité facultative',q.unit)}${input('roles','Fonctions prioritaires séparées par un point-virgule',(q.roles||[]).join('; '))}<label><input type="checkbox" name="essential" ${q.essential?'checked':''}> Question essentielle en mode Rapide</label><p class="muted">Cette modification s’applique aux prochaines saisies. Les réponses déjà collectées gardent leur question d’origine.</p><button type="submit" class="primary">Enregistrer le modèle</button></form>${act('library','Retour')}`;}return `<h1>Question personnalisée</h1><form id="iv-custom" class="card">${input('label','Question','','text','required maxlength="1000"')}${select('theme','Thème',THEMES.map(t=>[t.id,t.label]),'H')}${select('type','Type',[['text','Texte libre'],['boolean','Oui / Non'],['select','Choix unique'],['multi','Choix multiples'],['number','Nombre avec unité'],['date','Date ou période'],['location','Localisation GPS'],['observation','Observation et pièce jointe']])}${input('options','Suggestions séparées par un point-virgule')}${input('destination','Rubrique documentaire','Questions libres')}${input('unit','Unité facultative')}<label><input type="checkbox" name="reusable" ${iv?'':'checked disabled'}> Modèle réutilisable pour les prochains entretiens</label><p class="muted">Les réponses passées conservent leur question d’origine.</p><button type="submit" class="primary">Ajouter la question</button></form>${act(iv?'editor':'list','Retour')}`;}
 function library(){const mappings=settings.find(s=>s.id==='interview-mappings')?.value||{};return `<h1>Bibliothèque de questions</h1><p>${qlist().length} questions. Les choix locaux et rubriques documentaires ne réécrivent pas les réponses déjà saisies.</p>${act('custom','Ajouter un modèle réutilisable')}<form id="iv-mappings" class="card"><h2>Rubriques PTPF / PRSE</h2>${THEMES.map(t=>input('mapping-'+t.id,t.label,mappings[t.id]||t.destination||t.label)).join('')}<button type="submit" class="primary">Enregistrer les correspondances</button></form>${THEMES.map(t=>`<details><summary>${esc(t.label)}</summary>${qlist().filter(q=>q.theme===t.id).map(q=>`<p><strong>${esc(q.label)}</strong><br><span class="muted">${esc(q.type)} · ${esc(q.destination)}</span><br>${act('edit-question','Personnaliser',`data-id="${esc(q.id)}"`)}</p>`).join('')}</details>`).join('')}${act('list','Retour')}`;}
 function currentQuestion(){const qs=getQuestions({role:currentPerson().role,mode:iv.mode,answers:iv.answers,questions:qlist(),theme,search,includeAll:all,includeHidden:all});return qs[Math.max(0,Math.min(index,qs.length-1))];}
 function render(){if(destroyed||!isCurrent())return;root.classList.toggle('iv-quick',view==='editor'&&iv?.mode==='quick');root.innerHTML=({list,setup:()=>setup(panel),meeting:()=>meetingForm(panel),people:peoplePage,person:()=>personForm(panel),editor,compare,custom:customForm,library}[view]||list)();}
 async function filesSelected(files){
  if(!files.length)return;
  const qid=pendingQuestion,controls=[...root.querySelectorAll('input,textarea,select,button')].map(el=>[el,el.disabled]);
  for(const [el] of controls)el.disabled=true;
  saveStatus('Conservation des pièces…');
  const job=queue.catch(()=>{}).then(async()=>{
   const items=[];for(const file of files){if(file.size>db.MAX_ASSET_BYTES)throw new Error('Chaque pièce doit rester inférieure à 25 Mio.');items.push({id:crypto.randomUUID(),name:file.name,type:file.type||'application/octet-stream',size:file.size,blob:file,createdAt:timestamp()});}
   let next=updateInterview(iv,{assetIds:[...new Set([...iv.assetIds,...items.map(a=>a.id)])]});
   if(qid){const q=qlist().find(q=>q.id===qid),a=next.answers[qid]||{};next=writeAnswer(next,q,{assetIds:[...new Set([...(a.assetIds||[]),...items.map(a=>a.id)])]});}
   await db.saveInterview(next,items);iv=next;assets.push(...items);await db.saveInterviewDraft(next);
  });
  queue=job;
  try{await job;render();notify('Pièces conservées sur cet appareil.');}finally{for(const [el,disabled] of controls)el.disabled=disabled;}
 }

 async function exportReport(format){await queue.catch(()=>{});const options=reportOptions(iv?'individual':view==='list'?'comparison':reportKind),name=`Tety-${options.kind}-${iv?.id||filters.permit||today()}`;if(format==='csv')await deliver(new Blob([interviewCSV(options)],{type:'text/csv;charset=utf-8'}),name+'.csv');if(format==='word')await deliver(await createInterviewWordReport(options),name+'.docx');if(format==='html')await deliver(new Blob([interviewHTML(options)],{type:'text/html;charset=utf-8'}),name+'.html');if(format==='print'){const frame=document.createElement('iframe');frame.className='iv-print-frame';frame.title='Rapport prêt à imprimer';frame.srcdoc=interviewHTML(options);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};document.body.append(frame);setTimeout(()=>frame.remove(),60000);}}
 async function click(e){const btn=e.target.closest('[data-iv-action]');if(!btn)return;e.preventDefault();const action=btn.dataset.ivAction;try{btn.disabled=true;if(iv&&['list','compare','people','library'].includes(action)){await queue.catch(()=>{});iv=null;await reload();}
  if(action==='new'||action==='new-in-meeting'){iv=null;view='setup';panel=btn.dataset.id||'';render();}
  if(action==='list'){if(params.get('id')){location.hash='interviews';return;}view='list';panel='';render();}
  if(action==='meeting'||action==='edit-meeting'){view='meeting';panel=btn.dataset.id||'';render();}
  if(action==='people'){view='people';render();}if(action==='edit-person'){view='person';panel=btn.dataset.id;render();}
  if(action==='compare'){view='compare';panel='';render();}if(action==='library'){view='library';render();}
  if(action==='mode'){await patch({mode:iv.mode==='quick'?'complete':'quick'});index=0;render();}
  if(action==='all'){all=!all;index=0;render();}
  if(action==='previous'||action==='next'){index+=action==='next'?1:-1;render();query('.iv-question')?.scrollIntoView({block:'start'});}
  if(['choice','special','suggestion','revisit'].includes(action)){const q=currentQuestion(),a=iv.answers[q.id]||{},value=btn.dataset.value;let p={};if(action==='choice')p={value:q.type==='multi'?(Array.isArray(a.value)&&a.value.includes(value)?a.value.filter(x=>x!==value):[...(Array.isArray(a.value)?a.value:[]),value]):value,status:'answered'};if(action==='suggestion')p={value:[a.value,value].filter(Boolean).join('\n'),status:'answered'};if(action==='special')p={status:value,...(value==='verify'?{quality:'to-confirm'}:{})};if(action==='revisit')p={revisit:!a.revisit};await answer(q,p);render();}
  if(action==='note'){panel='notes';const d=query('#iv-notes');d.open=true;d.scrollIntoView({block:'center'});d.querySelector('textarea').focus();}
  if(action==='custom'){editingQuestionId=null;view='custom';render();}if(action==='edit-question'){editingQuestionId=btn.dataset.id;view='custom';render();}if(action==='editor'){view='editor';render();}
  if(action==='finish'){await patch({status:iv.status==='complete'?'draft':'complete'});render();notify(iv.status==='complete'?'Entretien terminé. Il reste modifiable.':'Entretien repris.');}
  if(action==='camera-question'){pendingQuestion=currentQuestion().id;query('#iv-camera').click();}
  if(action==='attach-question'||action==='attach-general'){pendingQuestion=action==='attach-question'?currentQuestion().id:null;query('#iv-files').click();}
  if(action==='gps'){const q=currentQuestion();if(!navigator.geolocation)throw new Error('GPS indisponible. Saisissez les coordonnées.');const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:0}));await answer(q,{value:{lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy},status:'answered'});render();}
  if(action==='learn'){const q=currentQuestion(),value=String(iv.answers[q.id]?.complement||readable(iv.answers[q.id]?.value)||'').trim();if(!value)throw new Error('Saisissez une réponse ou un complément pour mémoriser une suggestion.');const old=settings.find(s=>s.id==='interview-suggestions')?.value||{};await setting('interview-suggestions',{...old,[q.id]:[...new Set([...(old[q.id]||[]),value])].slice(-40)});notify('Suggestion locale ajoutée pour les prochaines saisies.');}
  if(['comparison','summary','missing'].includes(action)){reportKind=action==='summary'?'permit':action;render();}
  if(action==='meeting-report'){iv=null;view='compare';reportKind='meeting';panel='meeting:'+btn.dataset.id;render();}
  if(action.startsWith('export-'))await exportReport(action.slice(7));
  if(action==='backup'){await queue.catch(()=>{});const delivered=await deliver(await db.exportArchive(),'Tety-sauvegarde-'+today()+'.tety.json');if(delivered!==false)await setting('lastExport',timestamp());}
 }catch(err){notify(err.message||'Opération interrompue.');}finally{btn.disabled=false;}}
 async function changed(e){const el=e.target,n=el.name;if(!n&&!el.dataset.ivCaption&&!['iv-files','iv-camera'].includes(el.id))return;try{
  if(el.id==='iv-files'||el.id==='iv-camera'){await filesSelected([...el.files]);return;}
  if(n==='personId'){const section=query('#iv-new-person');section.hidden=!!el.value;for(const field of section.querySelectorAll('input,textarea'))field.disabled=!!el.value;return;}
  if(n==='iv-filter-permit'){filters.permit=el.value;render();return;}
  if(n.startsWith('filter-')){filters[n.slice(7)]=el.type==='checkbox'?el.checked:el.value;render();return;}
  if(!iv||view!=='editor')return;
  if(n==='iv-theme'||n==='iv-search'||n==='iv-jump'){if(n==='iv-theme')theme=el.value;if(n==='iv-search')search=el.value;index=n==='iv-jump'?Number(el.value):0;render();return;}
  const q=currentQuestion(),a=q?iv.answers[q.id]||{}:{};
  if(n==='iv-value'){let value=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;await answer(q,{value,status:'answered'});}
  if(n==='iv-period')await answer(q,{period:el.value,status:'answered'});
  if(n==='iv-other'){let value=el.value;if(q.type==='multi')value=[...(Array.isArray(a.value)?a.value.filter(v=>suggestionsFor(q).includes(v)):[]),...value.split(';').map(v=>v.trim()).filter(Boolean)];await answer(q,{value,status:'answered'});}
  if(n==='iv-complement')await answer(q,{complement:el.value});
  if(n==='iv-scope'){panel='reliability';await answer(q,{scope:{type:el.value,permitIds:el.value==='permits'?[...iv.permitIds]:[]}});render();}
  if(n==='answerPermits')await answer(q,{scope:{type:'permits',permitIds:[...root.querySelectorAll('[name="answerPermits"]:checked')].map(x=>x.value)}});
  if(n==='iv-provenance')await answer(q,{provenance:el.value});if(n==='iv-quality')await answer(q,{quality:el.value});if(n==='iv-source')await answer(q,{source:el.value});if(n==='iv-answer-date')await answer(q,{date:el.value});
  if(n==='iv-observation')await answer(q,{observationIds:el.value?[el.value]:[]});
  if(n==='iv-lat'||n==='iv-lng'){const lat=query('[name="iv-lat"]').value,lng=query('[name="iv-lng"]').value;if(lat!==''&&lng!==''){if(Math.abs(Number(lat))>90||Math.abs(Number(lng))>180)throw new Error('Coordonnées hors limites.');await answer(q,{value:{lat:Number(lat),lng:Number(lng)},status:'answered'});}}
  if(n==='iv-date')await patch({date:el.value});if(n==='iv-location')await patch({location:el.value});if(n==='iv-meeting')await patch({meetingId:el.value||null});
  if(n==='iv-permits'){const ids=[...root.querySelectorAll('[name="iv-permits"]:checked')].map(x=>x.value);const scoped=Object.values(iv.answers).flatMap(a=>a.scope?.type==='permits'?a.scope.permitIds:[]);if(scoped.some(id=>!ids.includes(id))||!ids.length&&Object.values(iv.answers).some(a=>a.scope?.type==='all')){el.checked=true;throw new Error('Ce permis est utilisé par une réponse. Modifiez d’abord sa portée.');}await patch({permitIds:ids});}
  if(n==='iv-notes')await patch({notes:el.value});
  if(el.dataset.ivCaption){const id=el.dataset.ivCaption;await patch({captions:{...(iv.captions||{}),[id]:el.value}});if(q&&(a.assetIds||[]).includes(id))await answer(q,{captions:{...(a.captions||{}),[id]:el.value}});}
 }catch(err){notify(err.message);}}
 function onInput(e){if(e.target.matches('input[type="checkbox"],select,input[type="file"]'))return;if(e.target.name==='iv-search')return;changed(e);}
 function onChange(e){if(e.target.matches('input[type="checkbox"],select,input[type="file"]')||e.target.name==='iv-search')changed(e);}
 async function submit(e){if(!e.target.id.startsWith('iv-'))return;e.preventDefault();e.stopPropagation();const f=e.target,data=new FormData(f),values=Object.fromEntries(data),button=f.querySelector('[type="submit"]');if(button)button.disabled=true;try{
  if(f.id==='iv-create'){let p=people.find(p=>p.id===data.get('personId'));if(!p){p=createPerson({...values,permitIds:data.getAll('permitIds')});await db.put('interviewPeople',p);people.push(p);}let ids=data.getAll('permitIds'),manual=String(data.get('manualPermit')||'').trim();if(manual){if(!/^\d{1,12}$/.test(manual))throw new Error('Le numéro doit contenir 1 à 12 chiffres.');if(!permits.some(p=>p.id===manual)){permits=[...permits,{id:manual,count:0,cells:[],status:null,adminVerificationRequired:true}];await setting('permits',permits);onPermitsChanged?.(permits);}ids=[...new Set([...ids,manual])];}iv=createInterview({personId:p.id,personSnapshot:p,meetingId:String(data.get('meetingId')||'')||null,permitIds:ids,date:values.date,location:values.location,mode:values.mode});await db.saveInterviewDraft(iv);location.hash='interviews?id='+encodeURIComponent(iv.id);}
  if(f.id==='iv-meeting'){const old=meetings.find(m=>m.id===f.dataset.id);const m=old?{...old,...values,id:old.id,permitIds:data.getAll('permitIds'),updatedAt:timestamp()}:createMeeting({...values,permitIds:data.getAll('permitIds')});await db.put('interviewMeetings',m);await reload();view='list';panel='';render();}
  if(f.id==='iv-person'){const old=people.find(p=>p.id===f.dataset.id);await db.put('interviewPeople',{...old,...values,id:old.id,updatedAt:timestamp()});await reload();view='people';render();}
  if(f.id==='iv-note'){iv=addInterviewNote(iv,{text:String(data.get('note')||'')});await persist();panel='notes';render();}
  if(f.id==='iv-question-edit'){const overrides=settings.find(s=>s.id==='interview-question-overrides')?.value||{};await setting('interview-question-overrides',{...overrides,[editingQuestionId]:{label:values.label,theme:values.theme,type:values.type,options:String(values.options||'').split(';').map(s=>s.trim()).filter(Boolean),suggestions:[],destination:values.destination,destinations:{PTPF:values.destination,PRSE:values.destination},unit:values.unit,roles:String(values.roles||'').split(';').map(s=>s.trim()).filter(Boolean),essential:data.has('essential')}});editingQuestionId=null;view='library';render();}
  if(f.id==='iv-custom'){const q={id:'custom-'+crypto.randomUUID(),label:values.label,theme:values.theme,type:values.type,options:String(values.options||'').split(';').map(s=>s.trim()).filter(Boolean),suggestions:[],unit:values.unit,essential:true,priority:'normale',roles:[],destination:values.destination};if(data.has('reusable'))await setting('interview-questions',[...(settings.find(s=>s.id==='interview-questions')?.value||[]),q]);else await patch({customQuestions:[...(iv.customQuestions||[]),q]});view=iv?'editor':'library';all=true;theme=q.theme;search='';index=0;render();}
  if(f.id==='iv-mappings'){await setting('interview-mappings',Object.fromEntries(THEMES.map(t=>[t.id,values['mapping-'+t.id]])));notify('Rubriques documentaires enregistrées.');}
 }catch(err){notify(err.message);}finally{if(button)button.disabled=false;}}
 await reload();if(!isCurrent())return {destroy(){},flush:()=>queue};if(params.get('id')){iv=interviews.find(x=>x.id===params.get('id'));if(iv){view='editor';const resume=getQuestions({role:currentPerson().role,mode:iv.mode,answers:iv.answers,questions:qlist()}).findIndex(q=>!iv.answers[q.id]);index=Math.max(0,resume);}else notify('Entretien introuvable sur cet appareil.');}
 root.addEventListener('click',click);root.addEventListener('input',onInput);root.addEventListener('change',onChange);root.addEventListener('submit',submit);render();if(iv?.mode==='quick')query('.iv-question')?.scrollIntoView({block:'start'});
 return {destroy(){destroyed=true;root.classList.remove('iv-quick');root.removeEventListener('click',click);root.removeEventListener('input',onInput);root.removeEventListener('change',onChange);root.removeEventListener('submit',submit);for(const url of urls.values())URL.revokeObjectURL(url);},flush:()=>queue};
}
